import numpy as np, collections
def solve(gin):
    g=np.array(gin); H,W=g.shape
    cnt={int(c):len(np.where(g==c)[0]) for c in np.unique(g)}
    mark=[c for c,n in cnt.items() if n==4][0]; bg=max(cnt,key=lambda c:cnt[c])
    ys,xs=np.where(g==mark); r0,r1,c0,c1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
    sub=g[r0:r1+1,c0:c1+1]; hh,ww=sub.shape
    # global comps of non-bg-non-mark cells
    visg=np.zeros_like(g,dtype=bool); info={}  # color -> set of global cells
    for y in range(H):
        for x in range(W):
            v=int(g[y,x])
            if v in (bg,mark): continue
            st=[(y,x)]; comp=set()
            while st:
                cy,cx=st.pop()
                if 0<=cy<H and 0<=cx<W and g[cy,cx]==v and not visg[cy,cx]:
                    visg[cy,cx]=True; comp.add((cy,cx)); st+=[(cy+1,cx),(cy-1,cx),(cy,cx+1),(cy,cx-1)]
            info.setdefault(v,set()).update(comp)
    bpos={}  # color (has >1 cell) -> (top,left,h,w)
    keys=collections.defaultdict(list)   # color -> list of global key cells
    for c,s in info.items():
        if len(s)>1: bpos[c]=(min(p[0] for p in s),min(p[1] for p in s),max(p[0] for p in s)-min(p[0] for p in s)+1,max(p[1] for p in s)-min(p[1] for p in s)+1)
        else:
            for p in s: keys[c].append(p)
    newcols={c for c in keys if c not in bpos}
    out=sub.copy(); res=[]
    for cv in newcols:
        for ak in keys[cv]:
            ayx=next(iter(keys.get(cv,[ak])))
            for ac,kas in keys.items():
                if ac==cv: continue
                if ac not in bpos: continue
                # try each anchor key orthogonal to this key cell
                for ax in kas:
                    dy,dx=ax[0]-ak[0],ax[1]-ak[1]
                    if abs(dy)+abs(dx)!=1: continue
                    tb,tl,bh,bw=bpos[ac]
                    if dx!=0:
                        tx=(tl+bw) if dx>0 else (tl-bw)
                        ty=tb
                    elif dy!=0:
                        ty=(tb+bh) if dy>0 else (tb-bh)
                        tx=tl
                    if 0<=ty<hh and 0<=tx<ww:
                        if all(out[ty+dr,tx+dc]==bg for dr in range(bh) for dc in range(bw)):
                            res.append((cv,ty,tx,bh,bw))
    for cv,ty,tx,h,w_ in sorted(set(res),key=lambda r:(r[1],r[2])):
        if all(out[ty+dr,tx+dc]==bg for dr in range(h) for dc in range(w_)):
            for dr in range(h):
                for dc in range(w_): out[ty+dr,tx+dc]=cv
    return [[int(v) for v in row] for row in out]
