    vis=np.zeros_like(g,dtype=bool)
    for y in range(H):
        for x in range(W):
            v=int(g[y,x])
            if v in (bg,mark) or vis[y,x]: continue
            st=[(y,x)]; comp=set()
            while st:
                cy,cx=st.pop()
                if 0<=cy<H and 0<=cx<W and not vis[cy,cx] and int(g[cy,cx])==v:
                    vis[cy,cx]=True; comp.add((cy,cx)); st+=[(cy+1,cx),(cy-1,cx),(cy,cx+1),(cy,cx-1)]
            if len(comp)==1:
                info.setdefault(v,[]).append(comp.pop())
            else:
                info.setdefault(v,[]).extend(comp)
    bpos={c:(min(p[0] for p in s),min(p[1] for p in s),max(p[0] for p in s)-min(p[0] for p in s)+1,max(p[1] for p in s)-min(p[1] for p in s)+1) for c,s in info.items() if len(s)>1}
