G=load(); ti=np.array(G['Test input']); gi=np.array(G['Demo pair 8 input']); go=np.array(G['Demo pair 8 output'])

def comps(a, bg=8):
    h,w=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(h):
        for j in range(w):
            if a[i,j]!=bg and not seen[i,j]:
                col=a[i,j]; st=[(i,j)]; seen[i,j]=True; cs=[]
                while st:
                    p,q=st.pop(); cs.append((p,q))
                    for dp,dq in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=p+dp,q+dq
                        if 0<=x<h and 0<=y<w and a[x,y]==col and not seen[x,y]:
                            seen[x,y]=True; st.append((x,y))
                out.append((col,len(cs),min(p for p,_ in cs),min(q for _,q in cs)))
    return out

